import type { Tweet } from '../twitter/twitter';

/**
 * Represents the report generated by the bot detection system for a tweet.
 */
export interface BotDetectionReport {
  chance: number;
  verifiedType?: Tweet['user']['verified_type'];
  isVerified: boolean;
  isVerifiedBusiness: boolean;
  isQuotedUserVerified: boolean;
  isQuotedUserBusiness: boolean;
  quotedUserVerifiedType?: Tweet['user']['verified_type'];
  isBot: boolean;
}

/**
 *
 * TODO: consider perhaps using a "no-trust" approach? Where everyone starts at 100 and evidence reduces the score?
 * @param tweet
 * @returns
 */
export function getDetectionReport(
  tweet: Tweet | undefined
): BotDetectionReport | undefined {
  if (!tweet) return;

  const report: BotDetectionReport = {
    chance: 0,
    isVerified: (tweet.user.verified || tweet.user.is_blue_verified) ?? false,
    verifiedType: undefined,
    isVerifiedBusiness:
      (!!tweet.user.professional &&
        tweet.user.professional.professional_type === 'Business') ||
      tweet.user.verified_type === 'Business', // TODO: probs too strict
    isQuotedUserVerified:
      (tweet.quoted_status?.user.verified ||
        tweet.quoted_status?.user.is_blue_verified) ??
      false,
    quotedUserVerifiedType: tweet.quoted_status?.user.verified_type,
    isQuotedUserBusiness:
      (!!tweet.quoted_status?.user.professional &&
        tweet.quoted_status?.user.professional.professional_type ===
          'Business') ||
      tweet.quoted_status?.user.verified_type === 'Business', // TODO: probs too strict
    isBot: false,
  };

  // Blue checks aren't worth anything anymore.
  if (report.isVerified && !report.isVerifiedBusiness) report.chance += 0.5;

  // quote-tweeting a blue checkmark also adds to the score, but not as much
  // (people get rage-baited)
  if (
    report.isQuotedUserVerified &&
    !report.quotedUserVerifiedType &&
    !report.isQuotedUserBusiness
  )
    report.chance += 0.1;

  report.isBot = report.chance >= 0.75; // arbitrary threshold for now
  return report;
}
